CREATE PROCEDURE "dba".verifica_objeto()BEGIN	IF EXISTS (SELECT procid			FROM sysprocedures			WHERE procname = 'u820_ce_10052_regu4materias') THEN		DROP PROCEDURE u820_ce_10052_regu4materias;	END IF;		ENDEND PROCEDURE;EXECUTE PROCEDURE "dba".verifica_objeto();DROP PROCEDURE "dba".verifica_objeto();-- Execute procedure "dba".u820_ce_10052_regu4materias("FCA", "001", "28503538-6", "10052", "04/10", 14)Create procedure u820_ce_10052_regu4materias (v_unidad_acad	like sga_alumnos.unidad_academica,				v_carrera		like sga_alumnos.carrera,				v_legajo		like sga_alumnos.legajo,				v_materia		like sga_cursadas.materia,				v_plan		like sga_alumnos.plan,				v_version		like sga_actas_examen.version)						returning smallint, varchar(255);begindefine v_resu numeric(1);define v_c_resu char(76);define n_cant_ciclo integer;define n_cant_apro integer;define vciclo_sup integer;define vciclo_sup_men char(76);let v_c_resu = " ";let vciclo_sup_men="";let v_c_resu = " ";   BEGIN      ON EXCEPTION IN (-206)        -- Tabla no existe continuo el proceso. Es por el delete de la        -- tabla temporal	      END EXCEPTION WITH RESUME;      -- Borro la tabla temporal	      DROP TABLE temp_materias_conjunto_10052;   END;-- Obtiene la cantidad de materias del Ciclo Básico AprobadasSelect materiaFrom sga_cursadas h Where h.resultado = "A"	and h.unidad_academica = v_unidad_acad	and h.carrera = v_carrera	and h.legajo = v_legajo	and materia in ("10032","10053","10069","10041")UNIONSelect materiaFrom vw_hist_academica h Where h.resultado = "A"	and h.unidad_academica = v_unidad_acad	and h.carrera = v_carrera	and h.legajo = v_legajo	and materia in ("10032","10053","10069","10041")Into temp temp_materias_conjunto_10052;Select count(distinct materia) Into n_cant_aprofrom temp_materias_conjunto_10052;-- *************************************************************************************************************************************-- U820-- Cantidad de materias regularizadas necesarios para pasar el control: se considera tener regularizada 4 materias   ("10032","10053","10069","10041") de la carrera.-- *************************************************************************************************************************************Execute procedure "dba".u820_ciclo_sup04 (v_unidad_acad,v_carrera,v_legajo,v_materia,v_plan,v_version) INTO vciclo_sup, vciclo_sup_men;if v_plan = "2004" then 	If n_cant_apro = 4 Then		let v_resu = 1;				if vciclo_sup= 1 then			let v_resu = 1;		else			let v_resu = -1;			let v_c_resu = "82005002";		end if;	else		let v_resu = -1;		let v_c_resu = "82005002";	end if;end if;if v_plan = "04/10" then 	If n_cant_apro = 4 Then		let v_resu = 1;				if vciclo_sup= 1 then			let v_resu = 1;		else			let v_resu = -1;			let v_c_resu = "82005002";		end if;	else		let v_resu = -2;		let v_c_resu = "82005002";	end if;end if;return v_resu, v_c_resu;end;end procedure;-- *************** Fin del procedimiento "dba".u820_ce_10052_regu4materias ******************-- *****************************************************************************-- Permisos del procedimiento "dba".u820_ce_10052_regu4materias-- *****************************************************************************revoke execute on "dba".u820_ce_10052_regu4materias from public;grant execute on "dba".u820_ce_10052_regu4materias to guarani; -- Rol de usuarios de Gestiongrant execute on "dba".u820_ce_10052_regu4materias to internet; -- Rol de usuario de Internet